export const size = 15;
export type Color = "Black" | "White";
export type Position = {
  board: number[];
  turn: Color;
  move: number;
  winner: Color | "draw" | null;
  last: number | null;
};
export function initial(): Position {
  return {
    board: Array(size * size).fill(0),
    turn: "Black",
    move: 0,
    winner: null,
    last: null,
  };
}
export function place(
  old: Position,
  row: number,
  column: number,
  color: Color,
): Position {
  if (old.winner) throw new Error("Match is finished");
  if (color !== old.turn) throw new Error("Not your turn");
  if (
    !Number.isInteger(row) ||
    !Number.isInteger(column) ||
    row < 1 ||
    row > size ||
    column < 1 ||
    column > size
  )
    throw new Error("Coordinates must be 1–15");
  const r = row - 1,
    c = column - 1,
    index = r * size + c,
    stone = color === "Black" ? 1 : 2;
  if (old.board[index]) throw new Error("Cell is occupied");
  const board = [...old.board];
  board[index] = stone;
  const count = (dr: number, dc: number) => {
    let n = 0,
      y = r + dr,
      x = c + dc;
    while (
      y >= 0 &&
      y < size &&
      x >= 0 &&
      x < size &&
      board[y * size + x] === stone
    ) {
      n++;
      y += dr;
      x += dc;
    }
    return n;
  };
  const won = [
    [1, 0],
    [0, 1],
    [1, 1],
    [1, -1],
  ].some(([dr, dc]) => 1 + count(dr, dc) + count(-dr, -dc) >= 5);
  return {
    board,
    move: old.move + 1,
    turn: color === "Black" ? "White" : "Black",
    winner: won ? color : old.move + 1 === size * size ? "draw" : null,
    last: index,
  };
}

files.src/style.css:
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  background: #faf9f6;
  color: #222;
  font-family: system-ui, sans-serif;
}
main {
  max-width: 880px;
  margin: auto;
  padding: 28px;
}
h1 {
  font-size: 26px;
  margin: 0 0 8px;
}
.hint {
  color: #666;
  font-size: 14px;
}
button,
input,
select {
  font: inherit;
}
button {
  cursor: pointer;
  border: 1px solid #ccc;
  border-radius: 9px;
  background: white;
  padding: 8px 12px;
}
button:disabled {
  cursor: default;
  opacity: 0.5;
}
.primary {
  background: #38324c;
  color: white;
  border-color: #38324c;
}
.toolbar,
form {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  margin: 20px 0;
}
input {
  min-width: 0;
  flex: 1;
  border: 1px solid #ccc;
  border-radius: 9px;
  padding: 10px;
}
ul {
  list-style: none;
  padding: 0;
}
li {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid #ddd;
}
li span {
  flex: 1;
}
.error {
  color: #b42318;
  white-space: pre-wrap;
}
.board {
  display: grid;
  grid-template-columns: repeat(15, minmax(0, 1fr));
  max-width: 680px;
  border: 1px solid #ba9658;
  background: #ecd09c;
}
.board button {
  position: relative;
  aspect-ratio: 1;
  padding: 0;
  border-radius: 0;
  border: 1px solid #d1ad6e;
  background: transparent;
}
.stone {
  display: block;
  width: 75%;
  height: 75%;
  border-radius: 50%;
  margin: auto;
  box-shadow: 0 1px 3px #666;
}
.black {
  background: #252525;
}
.white {
  background: #fff;
}
.last {
  outline: 2px solid #ba483b;
  outline-offset: -2px;
}
.choices {
  display: flex;
  gap: 12px;
  margin: 24px 0;
}
.choices button {
  font-size: 20px;
}
.players {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.player {
  padding: 16px;
  background: white;
  border: 1px solid #ddd;
  border-radius: 12px;
  flex: 1;
  min-width: 180px;
}
@media (prefers-color-scheme: dark) {
  body {
    background: #18181b;
    color: #fafafa;
  }
  .hint {
    color: #aaa;
  }
  button,
  input,
  select,
  .player {
    background: #27272a;
    color: #fafafa;
    border-color: #555;
  }
  .primary {
    background: #75659c;
  }
  .error {
    color: #ffa594;
  }
}

.board button:disabled { opacity: 1; }
